def build_candidate_vocabulary(ham_messages, max_words=100, min_freq=5):
    """Mine frequent ham words and merge with curated conversational terms."""
    freq = {}
    for msg in ham_messages[:500]:
        for w in str(msg).split():
            if 2 < len(w) < 10:          # keep typical conversational tokens
                freq[w] = freq.get(w, 0) + 1

    mined = [w for w, c in sorted(freq.items(),
             key=lambda x: (-x[1], x[0])) if c > min_freq][:max_words]

    curated = ["ok", "thanks", "sorry", "later", "today", "tomorrow",
               "meeting", "sure", "yeah", "see", "know", "think"]

    return sorted(set(mined) | set(curated))

import random

def epsilon_greedy_select(scorer, available_words):
    if random.random() < scorer['exploration_rate']:
        # EXPLORE: prefer words that have never been tested yet
        untested = [w for w in available_words
                    if w not in scorer['word_counts']]
        if untested:
            return random.choice(untested)
        return min(available_words,
                   key=lambda w: scorer['word_counts'].get(w, 0))
    # EXPLOIT: pick the best-performing word discovered so far
    return max(available_words,
               key=lambda w: scorer['word_scores'].get(w, 0))

def update_word_score(scorer, word, impact, alpha=0.3):
    """Exponential moving average smooths out one lucky or unlucky test."""
    old = scorer['word_scores'].get(word, 0.0)
    scorer['word_scores'][word] = (1 - alpha) * old + alpha * impact
    scorer['word_counts'][word] = scorer['word_counts'].get(word, 0) + 1
